n.loginUrl:
@js:
function login() {
  let une = source.getLoginInfoMap().get("账号")
  let pwd = source.getLoginInfoMap().get("密码")
  let yzm = getVerificationCode();
  if (une && pwd && yzm) {
    let body = String('username=' + une + '&password=' + pwd + '&checkcode=' + yzm + '&usecookie=315360000&action=login&submit=')
    let url = source.getKey() + '/login.php'
    let ck = java.post(url, body, { "Content-Type": "application/x-www-form-urlencoded" }).cookies()
    cookie=String(ck).match(/\{(.*?)\}/)[1].replace(/,/g, ';');
    let header = JSON.stringify({
      "Cookie": cookie
    })
    source.putLoginHeader(header)
  }
}

function getVerificationCode() {
   return str = java.getVerificationCode("https://www.37yq.com/checkcode.php?rand="+Math.random()) 
}

